CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY, name text NOT NULL, timezone text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, owner_id uuid NOT NULL REFERENCES accounts(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS entities(owner_id uuid NOT NULL REFERENCES accounts(id), id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('area','task','note','event','goal','routine','preferences')), data jsonb NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, PRIMARY KEY(owner_id,id));
CREATE INDEX IF NOT EXISTS entity_kind ON entities(owner_id,kind,updated_at,id);
CREATE UNIQUE INDEX IF NOT EXISTS occurrence_unique ON entities(owner_id,(data->>'routineId'),(data->>'occurrenceKey')) WHERE kind='task' AND data->>'routineId'<>'';
CREATE UNIQUE INDEX IF NOT EXISTS preferences_unique ON entities(owner_id,kind) WHERE kind='preferences';
CREATE TABLE IF NOT EXISTS operations(owner_id uuid NOT NULL REFERENCES accounts(id), id uuid NOT NULL, hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS activity(owner_id uuid NOT NULL REFERENCES accounts(id),id bigint GENERATED ALWAYS AS IDENTITY,entity_id uuid NOT NULL,action text NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS attachments(owner_id uuid NOT NULL, id uuid NOT NULL, parent_id uuid NOT NULL, name text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size>0 AND size<=10485760), object_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id,parent_id) REFERENCES entities(owner_id,id));
ALTER TABLE entities ENABLE ROW LEVEL SECURITY; ALTER TABLE entities FORCE ROW LEVEL SECURITY;
ALTER TABLE operations ENABLE ROW LEVEL SECURITY; ALTER TABLE operations FORCE ROW LEVEL SECURITY;
ALTER TABLE activity ENABLE ROW LEVEL SECURITY; ALTER TABLE activity FORCE ROW LEVEL SECURITY;
ALTER TABLE attachments ENABLE ROW LEVEL SECURITY; ALTER TABLE attachments FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS owner_only ON entities;
CREATE POLICY owner_only ON entities USING(owner_id=nullif(current_setting('app.owner',true),'')::uuid) WITH CHECK(owner_id=nullif(current_setting('app.owner',true),'')::uuid);
DROP POLICY IF EXISTS owner_only ON operations;
CREATE POLICY owner_only ON operations USING(owner_id=nullif(current_setting('app.owner',true),'')::uuid) WITH CHECK(owner_id=nullif(current_setting('app.owner',true),'')::uuid);
DROP POLICY IF EXISTS owner_only ON activity;
CREATE POLICY owner_only ON activity USING(owner_id=nullif(current_setting('app.owner',true),'')::uuid) WITH CHECK(owner_id=nullif(current_setting('app.owner',true),'')::uuid);
DROP POLICY IF EXISTS owner_only ON attachments;
CREATE POLICY owner_only ON attachments USING(owner_id=nullif(current_setting('app.owner',true),'')::uuid) WITH CHECK(owner_id=nullif(current_setting('app.owner',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON accounts,sessions,entities,operations,activity,attachments TO dayweave_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO dayweave_app;
ALTER TABLE attachments ADD COLUMN IF NOT EXISTS checksum text NOT NULL DEFAULT '';
